PRAGMA foreign_keys = OFF;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE,senha_hash TEXT NOT NULL,foco TEXT NOT NULL DEFAULT 'EFOMM',role TEXT NOT NULL DEFAULT 'aluno',ofensiva INTEGER NOT NULL DEFAULT 0,ultima_atividade TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_meta (meta_key TEXT PRIMARY KEY,meta_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS questoes (id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,concurso TEXT NOT NULL DEFAULT 'Outro',ano INTEGER NOT NULL DEFAULT 2024,numero INTEGER NOT NULL DEFAULT 0,pagina INTEGER NOT NULL DEFAULT 0,regiao TEXT NOT NULL DEFAULT '',materia TEXT NOT NULL DEFAULT 'Geral',assunto TEXT NOT NULL DEFAULT '',dificuldade TEXT NOT NULL DEFAULT 'Médio',enunciado TEXT NOT NULL,alt_a TEXT NOT NULL,alt_b TEXT NOT NULL,alt_c TEXT NOT NULL,alt_d TEXT NOT NULL,alt_e TEXT NOT NULL,gabarito INTEGER NOT NULL DEFAULT -1,gabarito_fonte TEXT NOT NULL DEFAULT '',gabarito_confianca REAL NOT NULL DEFAULT 0,gabarito_validado_em TEXT NULL,resolucao TEXT NOT NULL,origem TEXT NOT NULL DEFAULT '',exibir_preview INTEGER NOT NULL DEFAULT 0,ativo INTEGER NOT NULL DEFAULT 1,created_by INTEGER NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS importacoes (id INTEGER PRIMARY KEY AUTOINCREMENT,arquivo TEXT NOT NULL,concurso TEXT NOT NULL DEFAULT 'Outro',ano INTEGER NOT NULL DEFAULT 0,questoes INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'rascunho',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questao_imagens (id INTEGER PRIMARY KEY AUTOINCREMENT,questao_id INTEGER NULL,arquivo TEXT NOT NULL,legenda TEXT NOT NULL DEFAULT '',origem TEXT NOT NULL DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_paginas (id INTEGER PRIMARY KEY AUTOINCREMENT,arquivo TEXT NOT NULL,pagina INTEGER NOT NULL DEFAULT 1,arquivo_img TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,arquivo TEXT NOT NULL,concurso TEXT NOT NULL DEFAULT '',ano INTEGER NOT NULL DEFAULT 0,inicio INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,esperadas INTEGER NOT NULL DEFAULT 0,salvas INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'fila',erros TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS respostas (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,alternativa INTEGER NOT NULL,correta INTEGER NOT NULL DEFAULT 0,avaliavel INTEGER NOT NULL DEFAULT 1,tempo_seg INTEGER NOT NULL DEFAULT 0,confianca TEXT NOT NULL DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS favoritos (user_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,questao_id));
CREATE TABLE IF NOT EXISTS caderno_erros (user_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,motivo TEXT NOT NULL DEFAULT 'Errou a questão',anotacao TEXT NULL,revisada INTEGER NOT NULL DEFAULT 0,erro_tipo TEXT NOT NULL DEFAULT '',proxima_revisao TEXT NULL,revisoes INTEGER NOT NULL DEFAULT 0,ultima_revisao TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,questao_id));
CREATE TABLE IF NOT EXISTS comentarios (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,texto TEXT NOT NULL,aprovado INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,inicio TEXT NOT NULL,fim TEXT NULL,duracao_seg INTEGER NOT NULL DEFAULT 0,tipo TEXT NOT NULL DEFAULT 'livre',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trilhas (id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,nome TEXT NOT NULL,icone TEXT NOT NULL DEFAULT 'TR',cor TEXT NOT NULL DEFAULT '#1E5AA8',descricao TEXT NULL,ativo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS trilha_modulos (id INTEGER PRIMARY KEY AUTOINCREMENT,trilha_id INTEGER NOT NULL,titulo TEXT NOT NULL,ordem INTEGER NOT NULL DEFAULT 0,descricao TEXT NULL);
CREATE TABLE IF NOT EXISTS trilha_progresso (user_id INTEGER NOT NULL,modulo_id INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,modulo_id));
CREATE TABLE IF NOT EXISTS guia_artigos (id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,titulo TEXT NOT NULL,icone TEXT NOT NULL DEFAULT 'G',tempo TEXT NOT NULL DEFAULT '5 min',texto TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grupos (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,codigo TEXT NOT NULL UNIQUE,descricao TEXT NULL,dono_id INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS grupo_membros (grupo_id INTEGER NOT NULL,user_id INTEGER NOT NULL,entrou_em TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(grupo_id,user_id));
CREATE TABLE IF NOT EXISTS videoaulas (id INTEGER PRIMARY KEY AUTOINCREMENT,titulo TEXT NOT NULL,url TEXT NOT NULL DEFAULT '',concurso TEXT NOT NULL DEFAULT 'Outro',materia TEXT NOT NULL DEFAULT 'Geral',descricao TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ia_perguntas (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,questao_id INTEGER NULL,pergunta TEXT NOT NULL,resposta TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS metas_usuario (user_id INTEGER PRIMARY KEY,horas_semana REAL NOT NULL DEFAULT 10,questoes_semana INTEGER NOT NULL DEFAULT 150,simulados_semana INTEGER NOT NULL DEFAULT 1,updated_at TEXT NULL);
CREATE TABLE IF NOT EXISTS plano_diario (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,dia TEXT NOT NULL,tipo TEXT NOT NULL DEFAULT 'estudo',titulo TEXT NOT NULL,descricao TEXT NOT NULL DEFAULT '',link TEXT NOT NULL DEFAULT '',ordem INTEGER NOT NULL DEFAULT 0,concluido INTEGER NOT NULL DEFAULT 0,created_at TEXT NULL);
CREATE TABLE IF NOT EXISTS simulados_execucoes (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,modo TEXT NOT NULL DEFAULT 'personalizado',concurso TEXT NOT NULL DEFAULT '',materia TEXT NOT NULL DEFAULT '',qtd INTEGER NOT NULL DEFAULT 0,ids_json TEXT NOT NULL,config_json TEXT NOT NULL DEFAULT '{}',inicio TEXT NOT NULL,fim TEXT NULL,respondidas INTEGER NOT NULL DEFAULT 0,avaliadas INTEGER NOT NULL DEFAULT 0,acertos INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS simulado_respostas (execucao_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,alternativa INTEGER NOT NULL,correta INTEGER NOT NULL DEFAULT 0,avaliavel INTEGER NOT NULL DEFAULT 1,tempo_seg INTEGER NOT NULL DEFAULT 0,created_at TEXT NULL,PRIMARY KEY(execucao_id,questao_id));
CREATE TABLE IF NOT EXISTS questao_denuncias (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,questao_id INTEGER NOT NULL,tipo TEXT NOT NULL DEFAULT 'outro',detalhe TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'aberta',created_at TEXT NULL);
